"""Write docs/FULL_DATA_RESULTS.md: the full-dataset run next to the first (37% sample) run, every number from the JSON files.
    python3 scripts/make_full_report.py          (after:  AURAZ_OUT=public/full python3 ml/train_physionet_gbm.py  and  ml/audit_physionet.py)
"""
import json, os

R = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "public")
L = lambda *p: json.load(open(os.path.join(R, *p)))
a, b = L("metrics_physionet.json"), L("full", "metrics_physionet.json")           # first run, full run
aa, bb = L("audit_physionet.json"), L("full", "audit_physionet.json")
pct = lambda v: f"{100 * v:.0f}%"
ci = lambda c: f"{c[0]:.3f}–{c[1]:.3f}"
n = lambda m: m["cohorts"]["train"] + m["cohorts"]["calibration"] + m["cohorts"]["test"]
sa, sb = a["alerting"], b["alerting"]
mb = sb.get("model_at_sirs_false_alert_rate"); ma = sa.get("model_at_sirs_false_alert_rate")
out = []
w = out.append
w("# Full-dataset results (all PhysioNet 2019 training stays)\n")
w("*Generated by `scripts/make_full_report.py` from `public/full/*.json`. Same pipeline, features, split method, seeds and hyper-parameters as the first run; only the amount of data differs.*\n")
w(f"The first run used {n(a):,} stays ({a['cohorts']['test_septic']} septic in its test split), about 37% of the data (the PhysioNet server throttles downloads). This run uses **{n(b):,} stays** ({b['cohorts']['test_septic']} septic in the test split of {b['cohorts']['test']:,}).\n")
w("| | First run (37% sample) | **Full dataset** |\n|---|---|---|")
w(f"| Stays (train / calibration / test) | {a['cohorts']['train']:,} / {a['cohorts']['calibration']:,} / {a['cohorts']['test']:,} | {b['cohorts']['train']:,} / {b['cohorts']['calibration']:,} / {b['cohorts']['test']:,} |")
w(f"| Septic stays in test | {a['cohorts']['test_septic']} | {b['cohorts']['test_septic']} |")
w(f"| **AuraZ-R AUROC (95% CI)** | {a['auroc']:.3f} ({ci(a['auroc_ci95'])}) | **{b['auroc']:.3f}** ({ci(b['auroc_ci95'])}) |")
w(f"| AUPRC | {a['auprc']:.3f} | {b['auprc']:.3f} |")
w(f"| Without ICU-time features | {a['ablations']['without_icu_time']:.3f} | {b['ablations']['without_icu_time']:.3f} |")
w(f"| Without ICU-time and recency features | {a['ablations']['without_icu_time_and_recency']:.3f} | {b['ablations']['without_icu_time_and_recency']:.3f} |")
w(f"| Same features, logistic regression | {a['baselines']['logistic_same_rich_features']:.3f} | {b['baselines']['logistic_same_rich_features']:.3f} |")
w(f"| Conformal coverage, septic · non-septic (target 90%) | {pct(a['conformal']['coverage_septic_hours'])} · {pct(a['conformal']['coverage_nonseptic_hours'])} | {pct(b['conformal']['coverage_septic_hours'])} · {pct(b['conformal']['coverage_nonseptic_hours'])} |")
w(f"| Septic caught, low-burden setting (budget 15) | {pct(sa['model']['sensitivity'])} at {sa['model']['false_alerts_per_100_patient_days']:.1f} false alerts/100 patient-days | {pct(sb['model']['sensitivity'])} at {sb['model']['false_alerts_per_100_patient_days']:.1f} |")
if ma and mb:
    w(f"| Septic caught at SIRS's alarm rate (SIRS: first / full) | {pct(ma['sensitivity'])} (SIRS {pct(sa['baseline_sirs_rule']['sensitivity'])}) | {pct(mb['sensitivity'])} (SIRS {pct(sb['baseline_sirs_rule']['sensitivity'])}) |")
w("\n## External validation (train on one hospital, test on the other)\n")
w("| Train → test | First run: test septic · AUROC | Full dataset: test septic · AUROC (95% CI) | Full coverage septic · non-septic |\n|---|---|---|---|")
for k in bb["cross_hospital"]:
    x, y = aa["cross_hospital"][k], bb["cross_hospital"][k]
    cs = "—" if y["conformal"]["coverage_septic_hours"] is None else pct(y["conformal"]["coverage_septic_hours"])
    w(f"| {k.replace('train_', '').replace('_test_', ' → ')} | {x['test_septic']} · {x['auroc']:.3f} | {y['test_septic']} · **{y['auroc']:.3f}** ({ci(y['auroc_ci95'])}) | {cs} · {pct(y['conformal']['coverage_nonseptic_hours'])} |")
w(f"| Pooled random split (reference) | {aa['pooled_split']['test_septic']} · {aa['pooled_split']['auroc']:.3f} | {bb['pooled_split']['test_septic']} · {bb['pooled_split']['auroc']:.3f} ({ci(bb['pooled_split']['auroc_ci95'])}) | |")
w("\n## Subgroups, full dataset (same alert threshold for every group)\n")
w(f"{bb['subgroups']['operating_point']}\n")
w("| Subgroup | Septic stays | AUROC | Alert rate | Septic hours alerted |\n|---|---|---|---|---|")
for k, g in bb["subgroups"].items():
    if k == "operating_point": continue
    w(f"| {k} | {g.get('septic_stays', '—')} | {g['auroc']:.3f} | {g['alert_rate_pct']:.1f}% | {g['sensitivity_hour_pct']:.0f}% |" if "auroc" in g else f"| {k} | — | {g.get('note', '—')} | | |")
d = b["auroc"] - a["auroc"]
w(f"\n## Reading it\n- Pooled AUROC moved from {a['auroc']:.3f} to {b['auroc']:.3f} ({d:+.3f}); the confidence interval width went from {a['auroc_ci95'][1] - a['auroc_ci95'][0]:.3f} to {b['auroc_ci95'][1] - b['auroc_ci95'][0]:.3f}.")
w(f"- Across hospitals: {', '.join(f'{k.replace('train_', '').replace('_test_', ' → ')} {v['auroc']:.3f}' for k, v in bb['cross_hospital'].items())}.")
w("- All numbers here come from a retrospective, two-hospital dataset; this is research evidence, not clinical validation.")
open(os.path.join(R, "..", "docs", "FULL_DATA_RESULTS.md"), "w").write("\n".join(out) + "\n")
print("wrote docs/FULL_DATA_RESULTS.md")
